def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_empty_customer(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]   # 2500, no discount
    order(shop, "c1", ("LAMP", 2))                             # 12000 - 1200 = 10800
    order(shop, "c2", ("PEN", 1))                              # other customer, ignored
    shop.orders.handle_cancel(first)

    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 1, "lifetime_value_cents": 10800}


def test_lifetime_value_sums_totals_with_discount(shop):
    order(shop, "c2", ("LAMP", 2))  # gold: 12000 - 1800 = 10200
    order(shop, "c2", ("BOOK", 1))  # 2500, no discount
    response = shop.insights.handle_lifetime_value("c2")
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 12700}


def test_order_history_totals_match_order_summary_including_discount(shop):

